"""Local fire-response map agrees with the live public/private response model.
Road disconnections are controlled test fixtures; no natural fire events are forced.
"""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import json,hashlib
source=(ROOT/'assets/game.js').read_text();probe=r'''
window.__fireAudit={
 setup:()=>{__townTest.reset('settlement',42);G.autoBuild=false;__townTest.step(1);const homes=G.buildings.filter(b=>b.kind==='home'&&G.households[b.hh]?.people.length),home=homes.find(b=>publicFireResponse(b)>0)||homes[0],q=fireResponseInspection(home);return{addressId:home.id,cityReadiness:G.stats.preparedness,home:q,fireStations:G.buildings.filter(b=>b.kind==='fire'&&isPublicFacility(b)).map(b=>b.id),money:totalMoney(),save:__townTest.save()};},
 focus:id=>{const b=readBuild(id),p=iso(b.x,b.y);__townTest.capture({x:p[0],y:p[1],zoom:1.15});return p;},
 disconnect:id=>{const b=readBuild(id),changed=[];for(const [dx,dy] of roadOffsets){const x=b.x+dx,y=b.y+dy;if(x<0||y<0||x>=T||y>=T)continue;const at=roadId(x,y);if(G.tiles[at]===1){changed.push([at,G.tiles[at]]);G.tiles[at]=0;}}invalidateRoads(false);const q=fireResponseInspection(b);for(const [at,value] of changed){G.tiles[at]=value;}invalidateRoads(false);return{changed:changed.length,response:q,restored:fireResponseInspection(b),valid:validateTown()};},
 privateFixture:()=>{__townTest.reset('settlement',42);G.autoBuild=false;G.policy.privateServices=0;G.policy.defenseBudget=0;G.policy.aidBudget=0;G.policy.energyAidBudget=0;const b=G.buildings.find(b=>b.kind==='fire'),f=createFirm('fire',b.x,b.y,true,()=>b);G.region-=f.cash;f.privateService='fire';f.serviceFee=.8;f.wage=36;f.jobs=2;b.title={kind:'firm',id:f.id};const h=G.households.find(h=>h.people.length>=2&&sharesRoadNetwork(readBuild(h.home),b));G.region+=h.cash;h.cash=0;for(const id of h.people){const p=G.people[id];if(p.job>=0)G.firms[p.job].workers=G.firms[p.job].workers.filter(x=>x!==id);p.job=-1;p.searchAfter=G.day+10;}assignJobs();invalidateRoads(false);const total=totalMoney();__townTest.step(1);const home=readBuild(h.home),q=fireResponseInspection(home);return{firm:f.id,household:h.id,home:home.id,staff:f.workers.length,capacity:f.serviceCapacity,memberships:G.privateServiceProvision?.fireMembers||0,response:q,totalDrift:totalMoney()-total,valid:validateTown()};},
 overlayState:()=>overlay,
 overlay:id=>{const a=fireResponseOverlayValues().get(id);const same=fireResponseOverlayValues().get(id);if(a!==same)throw Error('Overlay response cache missed');const b=readBuild(id),changed=[];for(const [dx,dy] of roadOffsets){const x=b.x+dx,y=b.y+dy;if(x<0||y<0||x>=T||y>=T)continue;const at=roadId(x,y);if(G.tiles[at]===1){changed.push([at,G.tiles[at]]);G.tiles[at]=0;}}invalidateRoads(false);const blocked=fireResponseOverlayValues().get(id);for(const [at,value] of changed)G.tiles[at]=value;invalidateRoads(false);return{before:a,blocked,restored:fireResponseOverlayValues().get(id),valid:validateTown()};},
 replay:save=>{if(!__townTest.load(save))throw Error('seed archive failed');const total=totalMoney();__townTest.step(30);const after=__townTest.save();if(!__townTest.load(save))throw Error('restore failed');__townTest.step(30);return{equal:after===__townTest.save(),totalDrift:totalMoney()-total,valid:validateTown()};}
};'''
script=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js')
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-dev-shm-usage']);p=b.new_page(viewport={'width':1280,'height':850});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html);p.add_script_tag(content=script);p.locator('#newTown').click();p.locator('#pause').click()
 start=p.evaluate('__fireAudit.setup()');assert start['fireStations'],start
 p.evaluate('id=>__fireAudit.focus(id)',start['addressId']);box=p.locator('#view').bounding_box();p.mouse.click(box['x']+box['width']/2,box['y']+box['height']/2);text=p.locator('#panelBody').inner_text().lower();assert 'fire response at this property' in text and 'citywide emergency readiness' in text and 'estimated fire-damage reduction' in text and 'not fire prevention' in text,text
 p.locator('[data-panel=community]').click();p.locator('#overlayFireResponse').click();assert p.evaluate('__fireAudit.overlayState()')=='fireResponse'
 mapdata=p.evaluate('id=>__fireAudit.overlay(id)',start['addressId']);assert mapdata['before']['combined']==start['home']['combined'] and mapdata['blocked']['combined']<=mapdata['before']['combined'] and mapdata['restored']['combined']==mapdata['before']['combined'],mapdata
 disconnected=p.evaluate('id=>__fireAudit.disconnect(id)',start['addressId']);assert disconnected['changed']>0 and disconnected['response']['hasRoadAccess'] is False and disconnected['response']['municipal']==0 and disconnected['response']['independent']==0,disconnected
 assert disconnected['restored']['combined']==start['home']['combined'],disconnected
 replay=p.evaluate('s=>__fireAudit.replay(s)',start['save']);assert replay['equal'] and replay['valid']['ok'] and abs(replay['totalDrift'])<.01,replay
 private=p.evaluate('__fireAudit.privateFixture()');assert private['staff']>0 and private['capacity']>0 and private['memberships']>0 and private['response']['independent']>0 and private['response']['privateDistance'] is not None and abs(private['response']['independent']-private['response']['combined'])<1e-12 and abs(private['totalDrift'])<.01 and private['valid']['ok'],private
 assert not errors,errors
 sha=hashlib.sha256(source.encode()).hexdigest();out=ROOT/'docs/previews/urban8/fire-response-audit.json';out.write_text(json.dumps({'source_sha256':sha,'fixture':'Controlled seed42 municipal station/home with temporary test-only road isolation, plus a controlled independent brigade with one ordinary service day. No fire incident or casualties are injected. Only the private-provider fixture changes service provider state; no money or people are injected.','cityReadiness':start['cityReadiness'],'connectedHome':start['home'],'overlayInvalidation':mapdata,'disconnectedHome':disconnected,'privateBrigade':private,'saveReplay':replay,'errors':errors},indent=2)+'\n');print(json.dumps({'source_sha256':sha,'cityReadiness':start['cityReadiness'],'connectedHome':start['home'],'overlayInvalidation':mapdata,'disconnectedHome':disconnected,'privateBrigade':private,'saveReplay':replay,'errors':errors},indent=2));b.close()
